function validate(input) {
  const [text] = input;
  if (typeof text !== 'string' || text.length < 2 || text.length > 100000) return 'obj must be text of 2 to 10^5 characters.';
  if (text.includes('\u0000') || /\\u0000/i.test(text)) return 'obj must not contain the character U+0000.';
  // Write each bare undefined as a marker string, parse the JSON, then check its shape.
  let json = '', inString = false;
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    if (inString) {
      json += ch;
      if (ch === '\\') json += text[++i] ?? '';
      else if (ch === '"') inString = false;
    } else if (ch === '"') {
      inString = true;
      json += ch;
    } else if (text.startsWith('undefined', i)) {
      json += '"\\u0000"';
      i += 8;
    } else json += ch;
  }
  let value;
  try { value = JSON.parse(json); } catch { return 'obj must be JSON in which undefined may also appear as a value.'; }
  if (value === null || typeof value !== 'object') return 'obj must be an object or an array.';
  const stack = [value];
  while (stack.length) {
    const item = stack.pop();
    if (item === null || typeof item !== 'object') continue;
    if (!Array.isArray(item) && Object.hasOwn(item, '__proto__')) return 'No key may be "__proto__".';
    stack.push(...Object.values(item));
  }
  return null;
}

