function adapt(input, solve, kit) {
  const [text] = input;
  const marker = '\u0000';
  // Parse: each bare undefined becomes a marker string, and the markers become real undefined values.
  let json = '', inString = false;
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    if (inString) {
      json += ch;
      if (ch === '\\') json += text[++i] ?? '';
      else if (ch === '"') inString = false;
    } else if (ch === '"') {
      inString = true;
      json += ch;
    } else if (text.startsWith('undefined', i)) {
      json += '"\\u0000"';
      i += 8;
    } else json += ch;
  }
  const revive = (value) => {
    if (value === marker) return undefined;
    if (value !== null && typeof value === 'object') for (const key of Object.keys(value)) value[key] = revive(value[key]);
    return value;
  };
  const obj = revive(JSON.parse(json));
  const show = (value) => {
    if (value === undefined) return 'undefined';
    if (Array.isArray(value)) return `[${Array.from(value, show).join(',')}]`;
    if (value !== null && typeof value === 'object') return `{${Object.keys(value).map((key) => `${JSON.stringify(key)}:${show(value[key])}`).join(',')}}`;
    const written = JSON.stringify(value);
    if (written === undefined) throw new Error(`The result holds a ${typeof value}, which is not a JSON value.`);
    return written;
  };
  kit.trace(`undefinedToNull is called with ${text.length > 120 ? 'obj' : show(obj)}`);
  const result = solve(obj);
  if (result === null || typeof result !== 'object') throw new Error('undefinedToNull must return the object or array with undefined replaced by null.');
  const answer = show(result);
  kit.trace(`undefinedToNull returns ${answer.length > 120 ? 'the converted value' : answer}`);
  return answer;
}

