function generate(rand, size) {
  const small = size === 'small';
  const pick = (list) => list[Math.floor(rand() * list.length)];
  const keys = ['a', 'b', 'c', 'id', 'name', 'value', 'list', 'x', 'y', 'undefined', 'null', 'data'];
  const words = ['', 'a', 'undefined', 'null', 'hello', 'x y'];
  const maxDepth = small ? 3 : 6;
  const show = (value) => {
    if (value === undefined) return 'undefined';
    if (Array.isArray(value)) return `[${value.map(show).join(',')}]`;
    if (value !== null && typeof value === 'object') return `{${Object.keys(value).map((key) => `${JSON.stringify(key)}:${show(value[key])}`).join(',')}}`;
    return JSON.stringify(value);
  };
  const leaf = () => {
    const roll = rand();
    if (roll < 0.45) return undefined;
    if (roll < 0.55) return null;
    if (roll < 0.75) return Math.floor(rand() * 201) - 100;
    if (roll < 0.9) return pick(words);
    return rand() < 0.5;
  };
  const container = (depth) => {
    const count = small ? Math.floor(rand() * 4) : 2 + Math.floor(rand() * 5);
    const value = () => (depth < maxDepth && rand() < (small ? 0.3 : 0.45) ? container(depth + 1) : leaf());
    if (rand() < 0.5) return Array.from({ length: count }, value);
    const object = {};
    for (let i = 0; i < count; i++) object[pick(keys)] = value();
    return object;
  };
  let text = '';
  for (let tries = 0; tries < 50; tries++) {
    text = show(container(0));
    if (small || (text.length >= 2000 && text.length <= 10000)) break;
  }
  if (text.length > 10000) text = '[undefined,null,1]';
  return [text];
}
